    const recA = yA >= recentThresholdYear ? 1 : (yA > 0 ? 0 : -1);
    const recB = yB >= recentThresholdYear ? 1 : (yB > 0 ? 0 : -1);
    if (recA !== recB) return recB - recA;
    return yB - yA;
